#!/bin/bash
# Build the installable BeadsViewer .rpm — the RPM counterpart of
# tools/make-deb.sh, following the Nextpad++ app's make-rpm.sh recipe:
# a BINARY rpm from the already-staged payload (no Fedora build machinery),
# dependencies auto-generated by elfdeps in SONAME form (portable across
# Fedora / RHEL 10+ / openSUSE, whose package NAMES differ).
#
# Output: dist/BeadsViewerv<VER>_<debarch>.rpm (deb-style name, canonical
# rpm metadata inside).
set -euo pipefail
cd "$(dirname "$0")/.."

VER=$(sed -n 's/^project(NppBeads VERSION \([0-9.]*\).*/\1/p' CMakeLists.txt)
[ -n "$VER" ] || { echo "VERSION not found in CMakeLists.txt" >&2; exit 1; }
command -v rpmbuild >/dev/null || {
    echo "rpmbuild not found — install it with:  sudo apt install rpm" >&2; exit 1; }

ARCH=$(rpm --eval '%{_arch}')          # aarch64 / x86_64 (NOT dpkg names)

if [ -n "${NPP_JOBS:-}" ]; then
    JOBS=$NPP_JOBS
else
    MEM_MB=$(awk '/MemTotal/{print int($2/1024)}' /proc/meminfo)
    JOBS=$(nproc); CAP=$(( MEM_MB / 500 )); [ "$CAP" -lt 1 ] && CAP=1
    [ "$JOBS" -gt "$CAP" ] && JOBS=$CAP
fi

STAGE=$(mktemp -d /tmp/beadsviewer-rpm-stage-XXXXXX)
TOP=$(mktemp -d /tmp/beadsviewer-rpm-top-XXXXXX)
trap 'rm -rf "$STAGE" "$TOP"' EXIT
mkdir -p "$TOP"/{BUILD,RPMS,SOURCES,SPECS,SRPMS}

echo "── Building BeadsViewer $VER ($ARCH, -j$JOBS)"
cmake -B build-pkg -S . \
      -DCMAKE_BUILD_TYPE=Release \
      -DCMAKE_INSTALL_PREFIX=/usr
cmake --build build-pkg -j"$JOBS" --target BeadsViewer
DESTDIR="$STAGE" cmake --install build-pkg --component app > /dev/null

# %files generated from what was actually staged; every path QUOTED (the
# viewer tree carries vendor assets whose names could grow whitespace).
FILELIST="$TOP/beadsviewer-files.txt"
( cd "$STAGE"
  find . \( -type f -o -type l \) -printf '"/%P"\n'
  find . -type d -path './usr/share/beadsviewer*' -printf '%%dir "/%P"\n'
) | sort > "$FILELIST"
echo "── Staged $(grep -c . "$FILELIST") entries"

cat > "$TOP/SPECS/beadsviewer.spec" <<SPEC
# Binary spec: payload pre-built, handed to rpmbuild via --buildroot.
%define _topdir $TOP
%define _binary_payload w9.gzdio
# Keep the payload byte-identical with the .deb's: no strip, no build-id
# rewriting on a finished artifact.
%define __os_install_post %{nil}
%define _build_id_links none
%global __brp_check_rpaths %{nil}

Name:           beadsviewer
Version:        $VER
Release:        1
Summary:        Viewer for the Beads (bd) issue tracker
License:        GPL-3.0-or-later
URL:            https://github.com/nextpad-plus-plus-plugins/NppBeads.linux
BuildArch:      $ARCH
# Requires are auto-generated from the ELF payload (soname form) — gtk4,
# libadwaita, webkitgtk 6.0, json-glib, libsoup3, libsecret.
Provides:       beadsviewer = %{version}-%{release}

%description
Standalone desktop viewer for Beads (https://github.com/gastownhall/beads)
projects. Dashboard, Insights, Activity, Kanban board and a 3D dependency
graph; binds local projects (beads >= 1.3 Dolt workspaces or issues.jsonl,
live via the bd CLI when installed) and remote repositories read-only over
HTTP(S) (GitHub, self-hosted Gitea/Forgejo, raw URLs) with access tokens
kept in the Secret Service keyring. One window per project; editing
requires the separately installed bd CLI.

%post
command -v gtk-update-icon-cache >/dev/null 2>&1 && \\
    gtk-update-icon-cache -q /usr/share/icons/hicolor 2>/dev/null || true
command -v update-desktop-database >/dev/null 2>&1 && \\
    update-desktop-database -q /usr/share/applications 2>/dev/null || true
exit 0

%postun
command -v gtk-update-icon-cache >/dev/null 2>&1 && \\
    gtk-update-icon-cache -q /usr/share/icons/hicolor 2>/dev/null || true
command -v update-desktop-database >/dev/null 2>&1 && \\
    update-desktop-database -q /usr/share/applications 2>/dev/null || true
exit 0

%files -f $FILELIST

%changelog
* $(LC_ALL=C date '+%a %b %d %Y') Andrew Letov <aletik@gmail.com> - $VER-1
- Release $VER.
SPEC

rpmbuild -bb "$TOP/SPECS/beadsviewer.spec" \
         --buildroot "$STAGE" \
         --define "_topdir $TOP" \
         --quiet

case "$ARCH" in
  aarch64) DEBARCH=arm64 ;;
  x86_64)  DEBARCH=amd64 ;;
  *)       DEBARCH="$ARCH" ;;
esac
mkdir -p dist
OUT="dist/BeadsViewerv${VER}_${DEBARCH}.rpm"
cp "$TOP/RPMS/$ARCH/"*.rpm "./$OUT"
echo "── Built $OUT"
rpm -qp --info "./$OUT" 2>/dev/null | sed -n '1,6p'
echo "── Auto-generated Requires (soname form = portable):"
rpm -qp --requires "./$OUT" 2>/dev/null | grep -vE '^rpmlib' | sed 's/^/     /' | head -12
